namespace Wms.Persistence.Sqlite.V2.Migrations;

/// <summary>
/// FROZEN SQL of the <see cref="InitialV2Schema"/> migration. Once a database has applied this migration its definition
/// must never change: do not edit this file (helpers, lists and statements included) after B1 acceptance. Every later
/// schema change is a NEW migration class with its own SQL (see docs/v2-b1-identity.md, "Changing the schema").
/// It deliberately references nothing else in the project, so edits elsewhere cannot alter it.
/// <para>
/// Content: exactly the 16 approved business tables (docs/database-redesign-decisions.zh-CN.md §10-17), STRICT typed,
/// 64-bit AUTOINCREMENT keys (never reused), micro-unit INTEGER quantities, JSON TEXT arrays, check constraints, foreign
/// keys, unique indexes on normalized current codes, partial unique indexes for "one open X" rules, optimistic
/// <c>Version</c> columns and protective triggers. Uniqueness against historical codes is checked by the application
/// inside the write transaction; the history triggers are an ASCII-case backstop only.
/// </para>
/// </summary>
internal static class InitialV2SchemaSql
{
    private const long MaxPercentMicros = 100_000_000;
    private const string Roles = "('systemAdministrator','warehouseSupervisor','receivingClerk','shippingClerk')";
    private const string MaxQ = "999999999999999999";

    private const string Timestamps =
        "\"CreatedAt\" INTEGER NOT NULL,\n  \"UpdatedAt\" INTEGER NOT NULL,\n  \"Version\" INTEGER NOT NULL DEFAULT 1 CHECK (\"Version\" >= 1)";

    private static readonly string[] Tables =
    [
        "Users", "LoginSessions", "SystemSettings", "Units", "Categories", "Products", "ProductCategories", "Bins",
        "CountTasks", "CountResults", "InventoryTransactions", "InventoryTransactionLines", "SerializedItems",
        "TransactionLineItems", "ActivityLogs", "Alerts",
    ];

    private static readonly string[] AppendOnly =
        ["InventoryTransactions", "InventoryTransactionLines", "TransactionLineItems", "CountResults", "ActivityLogs"];

    private static readonly string[] NoDelete =
        ["Users", "LoginSessions", "SystemSettings", "Products", "Bins", "SerializedItems", "CountTasks", "Alerts"];

    public static IReadOnlyList<string> Up { get; } = BuildUp();

    public static IReadOnlyList<string> Down { get; } =
        Tables.AsEnumerable().Reverse().Select(t => $"DROP TABLE IF EXISTS \"{t}\";").ToList();

    private static string Bool(string column) => $"CHECK (\"{column}\" IN (0, 1))";

    private static string Text(string column, int max) =>
        $"CHECK (length(\"{column}\") BETWEEN 1 AND {max} AND \"{column}\" = trim(\"{column}\"))";

    private static string OptionalText(string column, int max) => $"CHECK (\"{column}\" IS NULL OR length(\"{column}\") <= {max})";

    private static string JsonArray(string column) => $"CHECK (json_valid(\"{column}\") AND json_type(\"{column}\") = 'array')";

    private static string Code(string column) =>
        $"CHECK (length(\"{column}\") BETWEEN 1 AND 128 AND \"{column}\" = trim(\"{column}\") " +
        $"AND \"{column}\" NOT GLOB '*[' || char(1) || '-' || char(31) || char(127) || ']*')";

    private static string Percent(string column) =>
        $"CHECK (\"{column}\" IS NULL OR (\"{column}\" BETWEEN 0 AND {MaxPercentMicros} AND \"{column}\" % 10000 = 0))";

    private static string Pascal(string operation) =>
        string.Concat(operation[..1].ToUpperInvariant(), operation[1..].ToLowerInvariant());

    private static List<string> BuildUp()
    {
        var sql = new List<string>
        {
            // 14 Users: fixed role array (validated by trigger), normalized username unique.
            $"""
            CREATE TABLE "Users" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "Username" TEXT NOT NULL {Text("Username", 64)},
              "NormalizedUsername" TEXT NOT NULL,
              "DisplayName" TEXT NOT NULL {Text("DisplayName", 100)},
              "PasswordHash" TEXT NOT NULL CHECK (length("PasswordHash") BETWEEN 1 AND 256),
              "Roles" TEXT NOT NULL {JsonArray("Roles")} CHECK (json_array_length("Roles") BETWEEN 1 AND 4),
              "Enabled" INTEGER NOT NULL {Bool("Enabled")},
              {Timestamps}
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_Users_NormalizedUsername\" ON \"Users\" (\"NormalizedUsername\");",

            // 16 SystemSettings: one row (Id = 1); technical number counters live here, no sequence table.
            $"""
            CREATE TABLE "SystemSettings" (
              "Id" INTEGER PRIMARY KEY CHECK ("Id" = 1),
              "DefaultRackLevels" INTEGER NOT NULL CHECK ("DefaultRackLevels" BETWEEN 1 AND 100),
              "DefaultCellsPerLevel" INTEGER NOT NULL CHECK ("DefaultCellsPerLevel" BETWEEN 1 AND 100),
              "LowThresholdMicros" INTEGER NOT NULL {Percent("LowThresholdMicros")},
              "HighThresholdMicros" INTEGER NOT NULL {Percent("HighThresholdMicros")},
              "SessionHours" INTEGER NOT NULL CHECK ("SessionHours" BETWEEN 1 AND 168),
              "LastSkuNumber" INTEGER NOT NULL DEFAULT 0 CHECK ("LastSkuNumber" >= 0),
              "LastBarcodeNumber" INTEGER NOT NULL DEFAULT 0 CHECK ("LastBarcodeNumber" >= 0),
              "LastSerialNumber" INTEGER NOT NULL DEFAULT 0 CHECK ("LastSerialNumber" >= 0),
              "LastTransactionNumber" INTEGER NOT NULL DEFAULT 0 CHECK ("LastTransactionNumber" >= 0),
              "LastCountTaskNumber" INTEGER NOT NULL DEFAULT 0 CHECK ("LastCountTaskNumber" >= 0),
              "UpdatedAt" INTEGER NOT NULL,
              "UpdatedById" INTEGER NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
              "Version" INTEGER NOT NULL DEFAULT 1 CHECK ("Version" >= 1),
              CHECK ("LowThresholdMicros" < "HighThresholdMicros")
            ) STRICT;
            """,

            // 2 Units
            $"""
            CREATE TABLE "Units" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "Name" TEXT NOT NULL {Text("Name", 32)},
              "NormalizedName" TEXT NOT NULL,
              "IsSystem" INTEGER NOT NULL {Bool("IsSystem")},
              {Timestamps}
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_Units_NormalizedName\" ON \"Units\" (\"NormalizedName\");",

            // 3 Categories: tree; sibling names unique (top level counts as siblings). Cycles: application.
            $"""
            CREATE TABLE "Categories" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "Name" TEXT NOT NULL {Text("Name", 64)},
              "NormalizedName" TEXT NOT NULL,
              "ParentId" INTEGER NULL REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
              {Timestamps},
              CHECK ("ParentId" IS NULL OR "ParentId" <> "Id")
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_Categories_SiblingName\" ON \"Categories\" (COALESCE(\"ParentId\", 0), \"NormalizedName\");",
            "CREATE INDEX \"IX_Categories_ParentId\" ON \"Categories\" (\"ParentId\");",

            // 1 Products: one current SKU and barcode (unique normalized), historical arrays, image in the row,
            // archive flag, and the creation request (actor + Idempotency-Key + body digest) for safe create retries.
            $"""
            CREATE TABLE "Products" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "Name" TEXT NOT NULL {Text("Name", 128)},
              "Sku" TEXT NOT NULL {Code("Sku")},
              "NormalizedSku" TEXT NOT NULL,
              "Barcode" TEXT NOT NULL {Code("Barcode")},
              "NormalizedBarcode" TEXT NOT NULL,
              "HistoricalSkus" TEXT NOT NULL DEFAULT '[]' {JsonArray("HistoricalSkus")},
              "HistoricalBarcodes" TEXT NOT NULL DEFAULT '[]' {JsonArray("HistoricalBarcodes")},
              "UnitId" INTEGER NOT NULL REFERENCES "Units" ("Id") ON DELETE RESTRICT,
              "DecimalPlaces" INTEGER NOT NULL CHECK ("DecimalPlaces" BETWEEN 0 AND 6),
              "SerialTracking" INTEGER NOT NULL {Bool("SerialTracking")},
              "Image" BLOB NULL CHECK ("Image" IS NULL OR length("Image") BETWEEN 1 AND 2097152),
              "ImageContentType" TEXT NULL CHECK ("ImageContentType" IS NULL OR "ImageContentType" IN ('image/png', 'image/jpeg')),
              "IsArchived" INTEGER NOT NULL DEFAULT 0 {Bool("IsArchived")},
              "ArchivedAt" INTEGER NULL,
              "CreatedById" INTEGER NOT NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
              "CreationRequestKey" TEXT NULL CHECK ("CreationRequestKey" IS NULL OR length("CreationRequestKey") BETWEEN 1 AND 64),
              "CreationRequestDigest" TEXT NULL CHECK ("CreationRequestDigest" IS NULL OR length("CreationRequestDigest") = 64),
              {Timestamps},
              CHECK ("SerialTracking" = 0 OR "DecimalPlaces" = 0),
              CHECK (("Image" IS NULL) = ("ImageContentType" IS NULL)),
              CHECK (("IsArchived" = 0) = ("ArchivedAt" IS NULL)),
              CHECK (("CreationRequestKey" IS NULL) = ("CreationRequestDigest" IS NULL))
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_Products_NormalizedSku\" ON \"Products\" (\"NormalizedSku\");",
            "CREATE UNIQUE INDEX \"UX_Products_NormalizedBarcode\" ON \"Products\" (\"NormalizedBarcode\");",
            "CREATE UNIQUE INDEX \"UX_Products_CreationRequest\" ON \"Products\" (\"CreatedById\", \"CreationRequestKey\") WHERE \"CreationRequestKey\" IS NOT NULL;",
            "CREATE INDEX \"IX_Products_UnitId\" ON \"Products\" (\"UnitId\");",

            // 4 ProductCategories
            """
            CREATE TABLE "ProductCategories" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "ProductId" INTEGER NOT NULL REFERENCES "Products" ("Id") ON DELETE RESTRICT,
              "CategoryId" INTEGER NOT NULL REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
              "CreatedAt" INTEGER NOT NULL
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_ProductCategories_Pair\" ON \"ProductCategories\" (\"ProductId\", \"CategoryId\");",
            "CREATE INDEX \"IX_ProductCategories_CategoryId\" ON \"ProductCategories\" (\"CategoryId\");",

            // 5 Bins: four position parts (no '-'), generated code, one product at a time with quantity, capacity and
            // optional threshold overrides; frozen count task; code history; archive flag. Positions never reused.
            $"""
            CREATE TABLE "Bins" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "Zone" TEXT NOT NULL {Text("Zone", 16)} CHECK (instr("Zone", '-') = 0),
              "Rack" TEXT NOT NULL {Text("Rack", 16)} CHECK (instr("Rack", '-') = 0),
              "Level" TEXT NOT NULL {Text("Level", 16)} CHECK (instr("Level", '-') = 0),
              "Cell" TEXT NOT NULL {Text("Cell", 16)} CHECK (instr("Cell", '-') = 0),
              "Code" TEXT NOT NULL CHECK ("Code" = "Zone" || '-' || "Rack" || '-' || "Level" || '-' || "Cell"),
              "NormalizedCode" TEXT NOT NULL,
              "HistoricalCodes" TEXT NOT NULL DEFAULT '[]' {JsonArray("HistoricalCodes")},
              "ProductId" INTEGER NULL REFERENCES "Products" ("Id") ON DELETE RESTRICT,
              "QuantityMicros" INTEGER NOT NULL DEFAULT 0 CHECK ("QuantityMicros" BETWEEN 0 AND {MaxQ}),
              "CapacityMicros" INTEGER NULL CHECK ("CapacityMicros" IS NULL OR "CapacityMicros" BETWEEN 1 AND {MaxQ}),
              "LowThresholdMicros" INTEGER NULL {Percent("LowThresholdMicros")},
              "HighThresholdMicros" INTEGER NULL {Percent("HighThresholdMicros")},
              "FrozenCountTaskId" INTEGER NULL REFERENCES "CountTasks" ("Id") ON DELETE RESTRICT,
              "IsArchived" INTEGER NOT NULL DEFAULT 0 {Bool("IsArchived")},
              "ArchivedAt" INTEGER NULL,
              {Timestamps},
              CHECK ("QuantityMicros" = 0 OR ("ProductId" IS NOT NULL AND "CapacityMicros" IS NOT NULL)),
              CHECK ("LowThresholdMicros" IS NULL OR "HighThresholdMicros" IS NULL OR "LowThresholdMicros" < "HighThresholdMicros"),
              CHECK (("IsArchived" = 0) = ("ArchivedAt" IS NULL)),
              CHECK ("IsArchived" = 0 OR ("QuantityMicros" = 0 AND "FrozenCountTaskId" IS NULL))
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_Bins_NormalizedCode\" ON \"Bins\" (\"NormalizedCode\");",
            "CREATE UNIQUE INDEX \"UX_Bins_FrozenCountTaskId\" ON \"Bins\" (\"FrozenCountTaskId\") WHERE \"FrozenCountTaskId\" IS NOT NULL;",
            "CREATE INDEX \"IX_Bins_ProductId\" ON \"Bins\" (\"ProductId\");",

            // 10 CountTasks: process state plus the persisted snapshot of the current round (blind: never served before
            // submit), what a cancel restores, and the creation request for safe start retries.
            $"""
            CREATE TABLE "CountTasks" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "Number" TEXT NOT NULL CHECK (length("Number") BETWEEN 1 AND 32),
              "BinId" INTEGER NOT NULL REFERENCES "Bins" ("Id") ON DELETE RESTRICT,
              "BinCode" TEXT NOT NULL CHECK (length("BinCode") BETWEEN 1 AND 128),
              "CreatorId" INTEGER NOT NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
              "CreatorName" TEXT NOT NULL CHECK (length("CreatorName") BETWEEN 1 AND 100),
              "CreatorRole" TEXT NOT NULL CHECK ("CreatorRole" IN {Roles}),
              "StartedAt" INTEGER NOT NULL,
              "Status" TEXT NOT NULL CHECK ("Status" IN ('inProgress', 'pendingConfirmation', 'completed', 'cancelled')),
              "CompletedAt" INTEGER NULL,
              "CurrentRound" INTEGER NOT NULL CHECK ("CurrentRound" >= 1),
              "HasUnresolvedInvestigation" INTEGER NOT NULL DEFAULT 0 {Bool("HasUnresolvedInvestigation")},
              "RoundStartedAt" INTEGER NULL,
              "RoundStartedById" INTEGER NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
              "RoundStartedByName" TEXT NULL,
              "RoundStartedByRole" TEXT NULL CHECK ("RoundStartedByRole" IS NULL OR "RoundStartedByRole" IN {Roles}),
              "RoundProductId" INTEGER NULL REFERENCES "Products" ("Id") ON DELETE RESTRICT,
              "RoundProductName" TEXT NULL,
              "RoundSku" TEXT NULL,
              "RoundBarcode" TEXT NULL,
              "RoundUnitName" TEXT NULL,
              "RoundDecimalPlaces" INTEGER NULL CHECK ("RoundDecimalPlaces" IS NULL OR "RoundDecimalPlaces" BETWEEN 0 AND 6),
              "RoundSerialTracking" INTEGER NULL CHECK ("RoundSerialTracking" IS NULL OR "RoundSerialTracking" IN (0, 1)),
              "RoundBookQuantityMicros" INTEGER NULL CHECK ("RoundBookQuantityMicros" IS NULL OR "RoundBookQuantityMicros" BETWEEN 0 AND {MaxQ}),
              "StatusBeforeRound" TEXT NULL CHECK ("StatusBeforeRound" IS NULL OR "StatusBeforeRound" IN ('pendingConfirmation', 'completed')),
              "CompletedAtBeforeRound" INTEGER NULL,
              "CancelledAt" INTEGER NULL,
              "CancelReason" TEXT NULL {OptionalText("CancelReason", 2000)},
              "CreationRequestKey" TEXT NULL CHECK ("CreationRequestKey" IS NULL OR length("CreationRequestKey") BETWEEN 1 AND 64),
              "CreationRequestDigest" TEXT NULL CHECK ("CreationRequestDigest" IS NULL OR length("CreationRequestDigest") = 64),
              "Version" INTEGER NOT NULL DEFAULT 1 CHECK ("Version" >= 1),
              CHECK ("Status" <> 'inProgress' OR ("RoundStartedAt" IS NOT NULL AND "RoundStartedById" IS NOT NULL
                AND "RoundStartedByName" IS NOT NULL AND "RoundStartedByRole" IS NOT NULL AND "RoundProductId" IS NOT NULL
                AND "RoundProductName" IS NOT NULL AND "RoundSku" IS NOT NULL AND "RoundBarcode" IS NOT NULL
                AND "RoundUnitName" IS NOT NULL AND "RoundDecimalPlaces" IS NOT NULL AND "RoundSerialTracking" IS NOT NULL
                AND "RoundBookQuantityMicros" IS NOT NULL)),
              CHECK (("Status" = 'completed') = ("CompletedAt" IS NOT NULL)),
              CHECK ("Status" <> 'cancelled' OR ("CancelledAt" IS NOT NULL AND "CancelReason" IS NOT NULL)),
              CHECK ("StatusBeforeRound" IS NULL OR "Status" = 'inProgress'),
              CHECK ("CompletedAtBeforeRound" IS NULL OR "StatusBeforeRound" = 'completed'),
              CHECK (("CreationRequestKey" IS NULL) = ("CreationRequestDigest" IS NULL))
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_CountTasks_Number\" ON \"CountTasks\" (\"Number\");",
            "CREATE UNIQUE INDEX \"UX_CountTasks_OneOpenPerBin\" ON \"CountTasks\" (\"BinId\") WHERE \"Status\" IN ('inProgress', 'pendingConfirmation') OR \"HasUnresolvedInvestigation\" = 1;",
            "CREATE UNIQUE INDEX \"UX_CountTasks_CreationRequest\" ON \"CountTasks\" (\"CreatorId\", \"CreationRequestKey\") WHERE \"CreationRequestKey\" IS NOT NULL;",

            // 11 CountResults: immutable facts of one submitted round with snapshots; difference = actual - book.
            $"""
            CREATE TABLE "CountResults" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "CountTaskId" INTEGER NOT NULL REFERENCES "CountTasks" ("Id") ON DELETE RESTRICT,
              "Round" INTEGER NOT NULL CHECK ("Round" >= 1),
              "BinId" INTEGER NOT NULL REFERENCES "Bins" ("Id") ON DELETE RESTRICT,
              "BinCode" TEXT NOT NULL CHECK (length("BinCode") BETWEEN 1 AND 128),
              "ProductId" INTEGER NOT NULL REFERENCES "Products" ("Id") ON DELETE RESTRICT,
              "ProductName" TEXT NOT NULL,
              "Sku" TEXT NOT NULL,
              "Barcode" TEXT NOT NULL,
              "UnitName" TEXT NOT NULL,
              "DecimalPlaces" INTEGER NOT NULL CHECK ("DecimalPlaces" BETWEEN 0 AND 6),
              "SerialTracking" INTEGER NOT NULL {Bool("SerialTracking")},
              "RoundStartedAt" INTEGER NOT NULL,
              "BookQuantityMicros" INTEGER NOT NULL CHECK ("BookQuantityMicros" BETWEEN 0 AND {MaxQ}),
              "ActualQuantityMicros" INTEGER NOT NULL CHECK ("ActualQuantityMicros" BETWEEN 0 AND {MaxQ}),
              "DifferenceMicros" INTEGER NOT NULL,
              "SubmittedById" INTEGER NOT NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
              "SubmittedByName" TEXT NOT NULL,
              "SubmittedByRole" TEXT NOT NULL CHECK ("SubmittedByRole" IN {Roles}),
              "SubmittedAt" INTEGER NOT NULL,
              "Note" TEXT NULL {OptionalText("Note", 2000)},
              CHECK ("DifferenceMicros" = "ActualQuantityMicros" - "BookQuantityMicros")
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_CountResults_TaskRound\" ON \"CountResults\" (\"CountTaskId\", \"Round\");",

            // 6 InventoryTransactions: one per successful operation; actor snapshot; request key + digest for retries.
            $"""
            CREATE TABLE "InventoryTransactions" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "Number" TEXT NOT NULL CHECK (length("Number") BETWEEN 1 AND 32),
              "Type" TEXT NOT NULL CHECK ("Type" IN ('receipt', 'shipment', 'movement', 'adjustment')),
              "ActorId" INTEGER NOT NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
              "ActorName" TEXT NOT NULL CHECK (length("ActorName") BETWEEN 1 AND 100),
              "ActorRole" TEXT NOT NULL CHECK ("ActorRole" IN {Roles}),
              "OccurredAt" INTEGER NOT NULL,
              "Source" TEXT NULL {OptionalText("Source", 200)},
              "Destination" TEXT NULL {OptionalText("Destination", 200)},
              "Reason" TEXT NULL {OptionalText("Reason", 2000)},
              "CountResultId" INTEGER NULL REFERENCES "CountResults" ("Id") ON DELETE RESTRICT,
              "RequestKey" TEXT NOT NULL CHECK (length("RequestKey") BETWEEN 1 AND 64),
              "RequestDigest" TEXT NOT NULL CHECK (length("RequestDigest") = 64),
              CHECK ("Type" <> 'adjustment' OR length(trim(coalesce("Reason", ''))) > 0),
              CHECK ("CountResultId" IS NULL OR "Type" = 'adjustment')
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_InventoryTransactions_Number\" ON \"InventoryTransactions\" (\"Number\");",
            "CREATE UNIQUE INDEX \"UX_InventoryTransactions_Request\" ON \"InventoryTransactions\" (\"ActorId\", \"RequestKey\");",
            "CREATE INDEX \"IX_InventoryTransactions_OccurredAt\" ON \"InventoryTransactions\" (\"OccurredAt\");",

            // 7 InventoryTransactionLines: product and bin snapshots, signed quantity, before/after of each side, packaging.
            $"""
            CREATE TABLE "InventoryTransactionLines" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "TransactionId" INTEGER NOT NULL REFERENCES "InventoryTransactions" ("Id") ON DELETE RESTRICT,
              "LineNo" INTEGER NOT NULL CHECK ("LineNo" >= 1),
              "ProductId" INTEGER NOT NULL REFERENCES "Products" ("Id") ON DELETE RESTRICT,
              "ProductName" TEXT NOT NULL,
              "Sku" TEXT NOT NULL,
              "Barcode" TEXT NOT NULL,
              "UnitName" TEXT NOT NULL,
              "DecimalPlaces" INTEGER NOT NULL CHECK ("DecimalPlaces" BETWEEN 0 AND 6),
              "FromBinId" INTEGER NULL REFERENCES "Bins" ("Id") ON DELETE RESTRICT,
              "FromBinCode" TEXT NULL,
              "ToBinId" INTEGER NULL REFERENCES "Bins" ("Id") ON DELETE RESTRICT,
              "ToBinCode" TEXT NULL,
              "QuantityMicros" INTEGER NOT NULL CHECK ("QuantityMicros" <> 0 AND "QuantityMicros" BETWEEN -{MaxQ} AND {MaxQ}),
              "FromBeforeMicros" INTEGER NULL CHECK ("FromBeforeMicros" IS NULL OR "FromBeforeMicros" BETWEEN 0 AND {MaxQ}),
              "FromAfterMicros" INTEGER NULL CHECK ("FromAfterMicros" IS NULL OR "FromAfterMicros" BETWEEN 0 AND {MaxQ}),
              "ToBeforeMicros" INTEGER NULL CHECK ("ToBeforeMicros" IS NULL OR "ToBeforeMicros" BETWEEN 0 AND {MaxQ}),
              "ToAfterMicros" INTEGER NULL CHECK ("ToAfterMicros" IS NULL OR "ToAfterMicros" BETWEEN 0 AND {MaxQ}),
              "PackagingUnit" TEXT NULL {OptionalText("PackagingUnit", 32)},
              "PackagingQuantityMicros" INTEGER NULL CHECK ("PackagingQuantityMicros" IS NULL OR "PackagingQuantityMicros" BETWEEN 1 AND {MaxQ}),
              "ConversionFactorMicros" INTEGER NULL CHECK ("ConversionFactorMicros" IS NULL OR "ConversionFactorMicros" BETWEEN 1 AND {MaxQ}),
              CHECK ("FromBinId" IS NOT NULL OR "ToBinId" IS NOT NULL),
              CHECK (("FromBinId" IS NULL) = ("FromBinCode" IS NULL) AND ("FromBinId" IS NULL) = ("FromBeforeMicros" IS NULL)
                AND ("FromBinId" IS NULL) = ("FromAfterMicros" IS NULL)),
              CHECK (("ToBinId" IS NULL) = ("ToBinCode" IS NULL) AND ("ToBinId" IS NULL) = ("ToBeforeMicros" IS NULL)
                AND ("ToBinId" IS NULL) = ("ToAfterMicros" IS NULL)),
              CHECK (("PackagingQuantityMicros" IS NULL) = ("ConversionFactorMicros" IS NULL)),
              CHECK ("PackagingUnit" IS NULL OR "PackagingQuantityMicros" IS NOT NULL)
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_InventoryTransactionLines_LineNo\" ON \"InventoryTransactionLines\" (\"TransactionId\", \"LineNo\");",
            "CREATE INDEX \"IX_InventoryTransactionLines_ProductId\" ON \"InventoryTransactionLines\" (\"ProductId\");",
            "CREATE INDEX \"IX_InventoryTransactionLines_FromBinId\" ON \"InventoryTransactionLines\" (\"FromBinId\");",
            "CREATE INDEX \"IX_InventoryTransactionLines_ToBinId\" ON \"InventoryTransactionLines\" (\"ToBinId\");",

            // 8 SerializedItems: one physical item; current and historical numbers; in stock exactly when it has a bin.
            $"""
            CREATE TABLE "SerializedItems" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "SerialNumber" TEXT NOT NULL {Code("SerialNumber")},
              "NormalizedSerialNumber" TEXT NOT NULL,
              "HistoricalSerialNumbers" TEXT NOT NULL DEFAULT '[]' {JsonArray("HistoricalSerialNumbers")},
              "ProductId" INTEGER NOT NULL REFERENCES "Products" ("Id") ON DELETE RESTRICT,
              "BinId" INTEGER NULL REFERENCES "Bins" ("Id") ON DELETE RESTRICT,
              "InStock" INTEGER NOT NULL {Bool("InStock")},
              {Timestamps},
              CHECK (("InStock" = 1) = ("BinId" IS NOT NULL))
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_SerializedItems_NormalizedSerialNumber\" ON \"SerializedItems\" (\"NormalizedSerialNumber\");",
            "CREATE INDEX \"IX_SerializedItems_ProductBin\" ON \"SerializedItems\" (\"ProductId\", \"BinId\");",

            // 9 TransactionLineItems: one row per item touched by a line, with the number at that time.
            $"""
            CREATE TABLE "TransactionLineItems" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "TransactionLineId" INTEGER NOT NULL REFERENCES "InventoryTransactionLines" ("Id") ON DELETE RESTRICT,
              "SerializedItemId" INTEGER NOT NULL REFERENCES "SerializedItems" ("Id") ON DELETE RESTRICT,
              "SerialNumber" TEXT NOT NULL {Code("SerialNumber")}
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_TransactionLineItems_Pair\" ON \"TransactionLineItems\" (\"TransactionLineId\", \"SerializedItemId\");",
            "CREATE INDEX \"IX_TransactionLineItems_SerializedItemId\" ON \"TransactionLineItems\" (\"SerializedItemId\");",

            // 12 ActivityLogs: success and failure, actor snapshot (null before identification), structured subjects.
            $"""
            CREATE TABLE "ActivityLogs" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "OccurredAt" INTEGER NOT NULL,
              "ActorId" INTEGER NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
              "ActorName" TEXT NULL {OptionalText("ActorName", 100)},
              "ActorRole" TEXT NULL CHECK ("ActorRole" IS NULL OR "ActorRole" IN {Roles}),
              "LoginName" TEXT NULL {OptionalText("LoginName", 16)},
              "Type" TEXT NOT NULL CHECK (length("Type") BETWEEN 1 AND 40),
              "Description" TEXT NOT NULL CHECK (length("Description") BETWEEN 1 AND 2000),
              "Success" INTEGER NOT NULL {Bool("Success")},
              "FailureCode" TEXT NULL {OptionalText("FailureCode", 64)},
              "FailureReason" TEXT NULL {OptionalText("FailureReason", 2000)},
              "Subjects" TEXT NOT NULL DEFAULT '[]' {JsonArray("Subjects")},
              "Changes" TEXT NULL CHECK ("Changes" IS NULL OR (json_valid("Changes") AND json_type("Changes") = 'array')),
              "TransactionId" INTEGER NULL REFERENCES "InventoryTransactions" ("Id") ON DELETE RESTRICT,
              "CountTaskId" INTEGER NULL REFERENCES "CountTasks" ("Id") ON DELETE RESTRICT,
              "CountResultId" INTEGER NULL REFERENCES "CountResults" ("Id") ON DELETE RESTRICT,
              CHECK ("Success" = 1 OR "FailureCode" IS NOT NULL),
              CHECK ("ActorId" IS NOT NULL OR "ActorRole" IS NULL)
            ) STRICT;
            """,
            "CREATE INDEX \"IX_ActivityLogs_OccurredAt\" ON \"ActivityLogs\" (\"OccurredAt\");",
            "CREATE INDEX \"IX_ActivityLogs_ActorId\" ON \"ActivityLogs\" (\"ActorId\");",

            // 13 Alerts: trigger snapshot (JSON object), open/resolved; one open capacity alert per bin and one open
            // discrepancy alert per task.
            $"""
            CREATE TABLE "Alerts" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "Type" TEXT NOT NULL CHECK ("Type" IN ('lowStock', 'highStock', 'overCapacity', 'countDiscrepancy')),
              "BinId" INTEGER NOT NULL REFERENCES "Bins" ("Id") ON DELETE RESTRICT,
              "ProductId" INTEGER NOT NULL REFERENCES "Products" ("Id") ON DELETE RESTRICT,
              "CountTaskId" INTEGER NULL REFERENCES "CountTasks" ("Id") ON DELETE RESTRICT,
              "CountResultId" INTEGER NULL REFERENCES "CountResults" ("Id") ON DELETE RESTRICT,
              "Message" TEXT NOT NULL CHECK (length("Message") BETWEEN 1 AND 500),
              "TriggerSnapshot" TEXT NOT NULL CHECK (json_valid("TriggerSnapshot") AND json_type("TriggerSnapshot") = 'object'),
              "CreatedAt" INTEGER NOT NULL,
              "Status" TEXT NOT NULL CHECK ("Status" IN ('open', 'resolved')),
              "ResolvedAt" INTEGER NULL,
              "ResolutionNote" TEXT NULL {OptionalText("ResolutionNote", 2000)},
              "Version" INTEGER NOT NULL DEFAULT 1 CHECK ("Version" >= 1),
              CHECK (("Type" = 'countDiscrepancy') = ("CountTaskId" IS NOT NULL)),
              CHECK (("Type" = 'countDiscrepancy') = ("CountResultId" IS NOT NULL)),
              CHECK (("Status" = 'open') = ("ResolvedAt" IS NULL))
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_Alerts_OpenCapacityPerBin\" ON \"Alerts\" (\"BinId\") WHERE \"Status\" = 'open' AND \"Type\" IN ('lowStock', 'highStock', 'overCapacity');",
            "CREATE UNIQUE INDEX \"UX_Alerts_OpenDiscrepancyPerTask\" ON \"Alerts\" (\"CountTaskId\") WHERE \"Status\" = 'open' AND \"Type\" = 'countDiscrepancy';",
            "CREATE INDEX \"IX_Alerts_StatusCreatedAt\" ON \"Alerts\" (\"Status\", \"CreatedAt\");",

            // 15 LoginSessions: token hash only; one open session per account; ended sessions are kept unchanged.
            $"""
            CREATE TABLE "LoginSessions" (
              "Id" INTEGER PRIMARY KEY AUTOINCREMENT,
              "UserId" INTEGER NOT NULL REFERENCES "Users" ("Id") ON DELETE RESTRICT,
              "CurrentRole" TEXT NOT NULL CHECK ("CurrentRole" IN {Roles}),
              "TokenHash" TEXT NOT NULL CHECK (length("TokenHash") = 64),
              "LoggedInAt" INTEGER NOT NULL,
              "ExpiresAt" INTEGER NOT NULL,
              "LoggedOutAt" INTEGER NULL,
              "RevokedAt" INTEGER NULL,
              "RevokeReason" TEXT NULL {OptionalText("RevokeReason", 200)},
              "Version" INTEGER NOT NULL DEFAULT 1 CHECK ("Version" >= 1),
              CHECK ("ExpiresAt" > "LoggedInAt"),
              CHECK (("RevokedAt" IS NULL) = ("RevokeReason" IS NULL)),
              CHECK ("LoggedOutAt" IS NULL OR "RevokedAt" IS NULL)
            ) STRICT;
            """,
            "CREATE UNIQUE INDEX \"UX_LoginSessions_TokenHash\" ON \"LoginSessions\" (\"TokenHash\");",
            "CREATE UNIQUE INDEX \"UX_LoginSessions_OneOpenPerUser\" ON \"LoginSessions\" (\"UserId\") WHERE \"LoggedOutAt\" IS NULL AND \"RevokedAt\" IS NULL;",
        };

        // Fixed role values, no duplicates (CHECK cannot hold a subquery; triggers can).
        foreach (var operation in new[] { "INSERT", "UPDATE" })
        {
            sql.Add($"""
                CREATE TRIGGER "TR_Users_Roles{Pascal(operation)}" BEFORE {operation} ON "Users"
                WHEN EXISTS (SELECT 1 FROM json_each(NEW."Roles") WHERE type <> 'text' OR value NOT IN {Roles})
                  OR (SELECT COUNT(DISTINCT value) FROM json_each(NEW."Roles")) <> json_array_length(NEW."Roles")
                BEGIN SELECT RAISE(ABORT, 'Users.Roles must hold distinct fixed role names'); END;
                """);
        }

        // A session's current role must be assigned to its account.
        sql.Add("""
            CREATE TRIGGER "TR_LoginSessions_RoleAssignedInsert" BEFORE INSERT ON "LoginSessions"
            WHEN NOT EXISTS (SELECT 1 FROM "Users" u, json_each(u."Roles") r WHERE u."Id" = NEW."UserId" AND r.value = NEW."CurrentRole")
            BEGIN SELECT RAISE(ABORT, 'LoginSessions.CurrentRole is not assigned to the account'); END;
            """);
        sql.Add("""
            CREATE TRIGGER "TR_LoginSessions_RoleAssignedUpdate" BEFORE UPDATE OF "CurrentRole" ON "LoginSessions"
            WHEN NOT EXISTS (SELECT 1 FROM "Users" u, json_each(u."Roles") r WHERE u."Id" = NEW."UserId" AND r.value = NEW."CurrentRole")
            BEGIN SELECT RAISE(ABORT, 'LoginSessions.CurrentRole is not assigned to the account'); END;
            """);

        // Identity of a session never changes, and an ended session is final.
        sql.Add("""
            CREATE TRIGGER "TR_LoginSessions_Immutable" BEFORE UPDATE ON "LoginSessions"
            WHEN NEW."Id" IS NOT OLD."Id" OR NEW."UserId" IS NOT OLD."UserId" OR NEW."TokenHash" IS NOT OLD."TokenHash"
              OR NEW."LoggedInAt" IS NOT OLD."LoggedInAt" OR NEW."ExpiresAt" IS NOT OLD."ExpiresAt"
              OR OLD."LoggedOutAt" IS NOT NULL OR OLD."RevokedAt" IS NOT NULL
            BEGIN SELECT RAISE(ABORT, 'LoginSessions: identity columns are fixed and ended sessions are final'); END;
            """);

        // The preset unit stays.
        sql.Add("""
            CREATE TRIGGER "TR_Units_SystemNoDelete" BEFORE DELETE ON "Units" WHEN OLD."IsSystem" = 1
            BEGIN SELECT RAISE(ABORT, 'The preset unit cannot be deleted'); END;
            """);

        // Backstop against reuse of another product's historical SKU or barcode (ASCII case-insensitive).
        foreach (var (column, history) in new[] { ("NormalizedSku", "HistoricalSkus"), ("NormalizedBarcode", "HistoricalBarcodes") })
        {
            sql.Add($"""
                CREATE TRIGGER "TR_Products_{history}ReservedInsert" BEFORE INSERT ON "Products"
                WHEN EXISTS (SELECT 1 FROM "Products" p, json_each(p."{history}") h WHERE upper(h.value) = NEW."{column}")
                BEGIN SELECT RAISE(ABORT, 'Products: code is reserved by a historical value'); END;
                """);
            sql.Add($"""
                CREATE TRIGGER "TR_Products_{history}ReservedUpdate" BEFORE UPDATE OF "{column}" ON "Products"
                WHEN EXISTS (SELECT 1 FROM "Products" p, json_each(p."{history}") h WHERE p."Id" <> NEW."Id" AND upper(h.value) = NEW."{column}")
                BEGIN SELECT RAISE(ABORT, 'Products: code is reserved by a historical value'); END;
                """);
        }

        // Creation metadata (who created it, with which request) is evidence for safe retries: never changes.
        sql.Add("""
            CREATE TRIGGER "TR_Products_CreationFixed" BEFORE UPDATE ON "Products"
            WHEN NEW."Id" IS NOT OLD."Id" OR NEW."CreatedById" IS NOT OLD."CreatedById" OR NEW."CreatedAt" IS NOT OLD."CreatedAt"
              OR NEW."CreationRequestKey" IS NOT OLD."CreationRequestKey" OR NEW."CreationRequestDigest" IS NOT OLD."CreationRequestDigest"
            BEGIN SELECT RAISE(ABORT, 'Products: creation metadata is immutable'); END;
            """);
        sql.Add("""
            CREATE TRIGGER "TR_CountTasks_CreationFixed" BEFORE UPDATE ON "CountTasks"
            WHEN NEW."Id" IS NOT OLD."Id" OR NEW."Number" IS NOT OLD."Number" OR NEW."BinId" IS NOT OLD."BinId"
              OR NEW."BinCode" IS NOT OLD."BinCode" OR NEW."CreatorId" IS NOT OLD."CreatorId"
              OR NEW."CreatorName" IS NOT OLD."CreatorName" OR NEW."CreatorRole" IS NOT OLD."CreatorRole"
              OR NEW."StartedAt" IS NOT OLD."StartedAt"
              OR NEW."CreationRequestKey" IS NOT OLD."CreationRequestKey" OR NEW."CreationRequestDigest" IS NOT OLD."CreationRequestDigest"
            BEGIN SELECT RAISE(ABORT, 'CountTasks: creation metadata is immutable'); END;
            """);

        sql.Add("""
            CREATE TRIGGER "TR_SerializedItems_HistoricalReservedInsert" BEFORE INSERT ON "SerializedItems"
            WHEN EXISTS (SELECT 1 FROM "SerializedItems" s, json_each(s."HistoricalSerialNumbers") h WHERE upper(h.value) = NEW."NormalizedSerialNumber")
            BEGIN SELECT RAISE(ABORT, 'SerializedItems: serial number is reserved by a historical value'); END;
            """);
        sql.Add("""
            CREATE TRIGGER "TR_SerializedItems_ProductFixed" BEFORE UPDATE OF "ProductId" ON "SerializedItems"
            WHEN NEW."ProductId" IS NOT OLD."ProductId"
            BEGIN SELECT RAISE(ABORT, 'SerializedItems: an item never changes product'); END;
            """);

        // Alerts: the only allowed change is open -> resolved (ResolvedAt, ResolutionNote, Version). Every opening
        // field is evidence and never changes; IS NOT compares NULLs correctly.
        sql.Add("""
            CREATE TRIGGER "TR_Alerts_Immutable" BEFORE UPDATE ON "Alerts"
            WHEN OLD."Status" <> 'open' OR NEW."Status" <> 'resolved'
              OR NEW."Id" IS NOT OLD."Id" OR NEW."Type" IS NOT OLD."Type" OR NEW."BinId" IS NOT OLD."BinId"
              OR NEW."ProductId" IS NOT OLD."ProductId" OR NEW."CountTaskId" IS NOT OLD."CountTaskId"
              OR NEW."CountResultId" IS NOT OLD."CountResultId" OR NEW."Message" IS NOT OLD."Message"
              OR NEW."TriggerSnapshot" IS NOT OLD."TriggerSnapshot" OR NEW."CreatedAt" IS NOT OLD."CreatedAt"
            BEGIN SELECT RAISE(ABORT, 'Alerts: only open -> resolved is allowed; opening evidence is immutable'); END;
            """);

        foreach (var table in AppendOnly)
        {
            foreach (var operation in new[] { "UPDATE", "DELETE" })
            {
                sql.Add($"CREATE TRIGGER \"TR_{table}_No{Pascal(operation)}\" BEFORE {operation} ON \"{table}\" " +
                        $"BEGIN SELECT RAISE(ABORT, '{table} is append-only'); END;");
            }
        }

        foreach (var table in NoDelete)
        {
            sql.Add($"CREATE TRIGGER \"TR_{table}_NoDelete\" BEFORE DELETE ON \"{table}\" " +
                    $"BEGIN SELECT RAISE(ABORT, '{table} rows are kept; archive instead'); END;");
        }

        return sql;
    }
}
